package com.adsh.app.ui

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.PathFillType
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.StrokeJoin
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.PathParser
import androidx.compose.ui.unit.dp

/**
 * 设置页用的 dsh 图标：path 逐字取自 dsh 前端产物
 * （dsh-web-frontend/dist/assets/index-*.js 里的 dsh-client-ui-primitives）。
 *
 * 由 scripts/dsh-icons3.py 生成，不要手改。
 */
object DshSettingIcons {

    private data class Part(
        val d: String,
        val tx: Float = 0f,
        val ty: Float = 0f,
        val evenOdd: Boolean = false,
        val stroke: Boolean = false,
        val strokeWidth: Float = 1.25f,
    )

    private fun icon(name: String, viewBox: Float, vararg parts: Part): ImageVector {
        val builder = ImageVector.Builder(
            name = name,
            defaultWidth = viewBox.dp,
            defaultHeight = viewBox.dp,
            viewportWidth = viewBox,
            viewportHeight = viewBox,
        )
        parts.forEach { part ->
            builder.addGroup(translationX = part.tx, translationY = part.ty)
            val nodes = PathParser().parsePathString(part.d).toNodes()
            if (part.stroke) {
                builder.addPath(
                    pathData = nodes,
                    stroke = SolidColor(Color.Black),
                    strokeLineWidth = part.strokeWidth,
                    strokeLineJoin = StrokeJoin.Round,
                )
            } else {
                builder.addPath(
                    pathData = nodes,
                    pathFillType = if (part.evenOdd) PathFillType.EvenOdd else PathFillType.NonZero,
                    fill = SolidColor(Color.Black),
                )
            }
            builder.clearGroup()
        }
        return builder.build()
    }

